const cfg=$('⚙️ CONTROL PANEL').first().json;
const rows=Array.isArray($input.first().json)?$input.first().json:($input.first().json.data||[]);
const queued=rows.length;
const need=(cfg.bufferDays||3)*(cfg.videosPerRun||1);
return [{ json:{ ...cfg, queued, need, generate: queued<need } }];

const cfg=$('🧠 Buffer Decision').first().json;
const topRaw=$('📈 Research: Top Performers').first().json;
const recRaw=$('🗂️ Research: Recent Topics').first().json;
const top=(Array.isArray(topRaw)?topRaw:(topRaw.data||[])).map(r=>`\"${r.title}\" (score ${r.performance}, ${r.views} views)`);
const recent=(Array.isArray(recRaw)?recRaw:(recRaw.data||[])).map(r=>r.topic).filter(Boolean);
const now=new Date();const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
const research={ topPerformers: top, avoidTopics: recent, month: months[now.getMonth()], year: now.getFullYear() };
const sys=`You are a senior short-form content strategist (Agent 1). Niche: ${cfg.niche}. Use DATA to choose the next winning topic. Prioritise angles similar to past top performers; avoid repeating recent topics. Respond with strict JSON only.`;
const dataBlock = top.length ? `Past top performers to learn from:\n- ${top.join('\n- ')}` : 'No performance history yet — pick a proven evergreen angle for the niche.';
const usr=`${dataBlock}\n\nRecent topics to AVOID duplicating:\n${recent.length?('- '+recent.join('\n- ')):'(none yet)'}\n\nMonth: ${research.month} ${research.year}.\nReturn JSON: {\"topic\":\"specific, fresh topic\",\"content_pillar\":\"education|inspiration|story|listicle|howto\",\"target_audience\":\"who it's for\",\"hook_angle\":\"the curiosity/tension angle\",\"why_it_retains\":\"1 sentence\"}`;
return [{ json:{ ...cfg, research, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.85, max_tokens:500 } } }];

const prev=$('🧭 Agent1: Data-Driven Strategy').first().json;
const raw=$input.first().json.choices[0].message.content;
let s={};try{s=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)s=JSON.parse(m[0]);}
const sys='You are an elite short-form video scriptwriter (Agent 2). Write a high-retention 30-45s script using the framework: HOOK (0-3s, create curiosity/tension) -> 3-4 fast value BEATS -> PAYOFF -> CTA. Each beat is one scene with its own narration, bold on-screen caption, and a concrete b-roll search keyword. Respond with strict JSON only.';
const usr=`Topic: ${s.topic}
Audience: ${s.target_audience}
Hook angle: ${s.hook_angle}
Style: ${prev.videoStyle}
Rules: spoken script total 90-130 words; captions punchy (max 6 words); b-roll keywords are simple visual nouns (e.g. "sunrise running", "city night lights").
Return JSON: {"hook":"first spoken line","scenes":[{"narration":"...","on_screen_text":"...","broll_keyword":"..."}],"cta":"final spoken CTA line"}
Provide 4 to 5 scenes.`;
return [{ json:{ ...prev, topic:s.topic, content_pillar:s.content_pillar, target_audience:s.target_audience, hook_angle:s.hook_angle, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.85, max_tokens:1100 } } }];

const prev=$('✍️ Agent2: Build Script Request').first().json;
const raw=$input.first().json.choices[0].message.content;
let sc={};try{sc=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)sc=JSON.parse(m[0]);}
const scenes=(sc.scenes||[]).slice(0,6).map((x,i)=>({ idx:i, narration:x.narration||'', on_screen_text:x.on_screen_text||'', broll_keyword:x.broll_keyword||prev.topic }));
const fullScript=[sc.hook,...scenes.map(s=>s.narration),sc.cta].filter(Boolean).join(' ');
const sys='You are a YouTube/TikTok SEO + packaging expert (Agent 4). Generate 3 title options then pick the most clickable. Respond with strict JSON only.';
const usr=`Topic: ${prev.topic}\nAudience: ${prev.target_audience}\nReturn JSON: {\"title\":\"best title, max 70 chars, curiosity-driven, no clickbait lies\",\"alt_titles\":[\"opt2\",\"opt3\"],\"description\":\"2-3 sentences with keywords + CTA\",\"tags\":\"12 comma-separated keywords\",\"hashtags\":\"8 space-separated #tags\"}`;
return [{ json:{ ...prev, hook:sc.hook||'', scenes, cta:sc.cta||'', script:fullScript, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.7, max_tokens:500 } } }];

const prev=$('🔍 Agent4: Build SEO Request').first().json;
const raw=$input.first().json.choices[0].message.content;
let o={};try{o=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)o=JSON.parse(m[0]);}
const thumbPrompt=`Bold YouTube/Shorts thumbnail for \"${prev.topic}\". High emotional contrast, vibrant cinematic lighting, single clear focal subject, leaves space for text, 9:16 vertical friendly, no text in image.`;
return [{ json:{ ...prev, title:(o.title||prev.topic||'').slice(0,95), alt_titles:o.alt_titles||[], description:o.description||'', tags:o.tags||'', hashtags:o.hashtags||'', dalleBody:{ model:'dall-e-3', prompt:thumbPrompt, n:1, size:'1024x1792', quality:'standard', response_format:'url' } } }];

const prev=$('🎨 Agent3: Build Thumbnail Request').first().json;
const resp=$input.first().json;
let url='';try{url=resp.data[0].url;}catch(e){}
return [{ json:{ ...prev, rawThumbUrl:url } }];

const prev=$('📋 Get Thumb URL').first().json;
const resp=$input.first().json;
let hosted='';try{hosted=resp.data.url||resp.data.display_url;}catch(e){}
const master={ platform:prev.platform, postingMethod:prev.postingMethod, voice:prev.voice, niche:prev.niche, queued:prev.queued, scheduleHour:prev.scheduleHour, topic:prev.topic, content_pillar:prev.content_pillar, target_audience:prev.target_audience, hook:prev.hook, cta:prev.cta, script:prev.script, scenes:prev.scenes, title:prev.title, description:prev.description, tags:prev.tags, hashtags:prev.hashtags, thumbnail_url: hosted||prev.rawThumbUrl, research:prev.research };
return [{ json:{ ...master, scenes: master.scenes } }];

// run once for all items: zip scenes with their pexels responses
const master=$('🧩 Assemble Record').first().json;
const scenes=$('🎬 Split Scenes').all().map(i=>i.json);
const responses=$input.all().map(i=>i.json);
function pickVideo(r){ try{ const vids=r.videos||[]; if(!vids.length) return ''; const files=vids[0].video_files||[]; const portrait=files.filter(f=>f.height>=f.width); const pool=portrait.length?portrait:files; pool.sort((a,b)=>(a.height||0)-(b.height||0)); const mid=pool[Math.floor(pool.length/2)]||pool[0]; return mid?mid.link:''; }catch(e){ return ''; } }
const built=scenes.map((s,i)=>({ ...s, video_url: pickVideo(responses[i]||{}) }));
// Build JSON2Video multi-scene movie
const movieScenes=built.map(s=>({ comment:s.broll_keyword, elements:[
  s.video_url ? { type:'video', src:s.video_url, duration:-1, fit:'cover' } : { type:'image', src:master.thumbnail_url, duration:-1, zoom:2 },
  { type:'voice', text:s.narration, voice: master.voice||'en-US-AriaNeural' },
  { type:'text', text:s.on_screen_text, position:'center', settings:{ 'font-size':70, 'font-family':'Oswald', 'font-weight':'700', color:'#ffffff', 'background-color':'rgba(0,0,0,0.45)', padding:18 } }
]}));
const movie={ resolution:'instagram-story', quality:'high', scenes:movieScenes };
return [{ json:{ ...master, scenes:built, json2videoBody:movie } }];

const m=$('🎞️ Agent5: Build Multi-Scene Movie').first().json;
const resp=$input.first().json;
const renderId=resp.project||(resp.movie&&resp.movie.project)||resp.id||null;
const now=new Date();const sched=new Date(now);sched.setHours(m.scheduleHour||14,0,0,0);if(sched<=now)sched.setDate(sched.getDate()+1);sched.setDate(sched.getDate()+(m.queued||0));
return [{ json:{ platform:m.platform, niche:m.niche, topic:m.topic, hook:m.hook, cta:m.cta, content_pillar:m.content_pillar, target_audience:m.target_audience, script:m.script, scenes:m.scenes, title:m.title, description:m.description, tags:m.tags, hashtags:m.hashtags, thumbnail_url:m.thumbnail_url, research_used:m.research, render_id:renderId, status: renderId?'rendering':'failed', scheduled_time:sched.toISOString(), error_notes: renderId?null:('Render submit failed: '+JSON.stringify(resp).slice(0,200)) } }];

const row=$('🔄 Check Each Render').first().json;
const resp=$input.first().json;
const movie=resp.movie||resp;
const done=movie.status==='done'&&movie.url;
return [{ json:{ id:row.id, ready:done, video_url: done?movie.url:null } }];

const row=$('🔄 Publish Each').first().json;
const cfg=$('⚙️ CONTROL PANEL').first().json;
const plat=row.platform||cfg.platform;
const profiles=[];
if(plat==='youtube'||plat==='both'){ if($vars.BUFFER_PROFILE_ID_YOUTUBE) profiles.push($vars.BUFFER_PROFILE_ID_YOUTUBE); }
if(plat==='tiktok'||plat==='both'){ if($vars.BUFFER_PROFILE_ID_TIKTOK) profiles.push($vars.BUFFER_PROFILE_ID_TIKTOK); }
const text=(row.title||'')+'\n\n'+(row.description||'')+'\n\n'+(row.hashtags||'');
const parts=[];profiles.forEach(p=>parts.push('profile_ids[]='+encodeURIComponent(p)));parts.push('text='+encodeURIComponent(text));parts.push('media[video]='+encodeURIComponent(row.video_url||''));parts.push('media[thumbnail]='+encodeURIComponent(row.thumbnail_url||''));parts.push('now=true');
return [{ json:{ id:row.id, bufferBody:parts.join('&') } }];

const row=$('🔄 Publish Each').first().json;
const resp=$input.first().json;
const ok=resp.success||(resp.updates&&resp.updates.length>0);
const pid=(resp.updates&&resp.updates[0]&&resp.updates[0].id)||null;
return [{ json:{ id:row.id, status: ok?'published':'failed', platform:'buffer', youtube_video_id:null, tiktok_video_id:pid, published_at: ok?new Date().toISOString():null, error_notes: ok?null:('Buffer post failed: '+JSON.stringify(resp).slice(0,200)) } }];

const row=$('🔄 Publish Each').first().json;
const resp=$input.first().json;
const vid=resp.id||(resp.id&&resp.id.videoId)||null;
return [{ json:{ id:row.id, status:'published', platform:'youtube', youtube_video_id:vid, tiktok_video_id:null, published_at:new Date().toISOString(), error_notes:null } }];

const row=$('🔄 Publish Each').first().json;
const resp=$input.first().json;
let pubId=null;try{pubId=resp.data.publish_id;}catch(e){}
const ok=!!pubId;
return [{ json:{ id:row.id, status: ok?'published':'failed', platform:'tiktok', youtube_video_id:null, tiktok_video_id:pubId, published_at: ok?new Date().toISOString():null, error_notes: ok?null:('TikTok publish failed: '+JSON.stringify(resp).slice(0,200)) } }];

const row=$('🔄 Each Video').first().json;
const resp=$input.first().json;
let s={};try{s=resp.items[0].statistics;}catch(e){}
const views=+(s.viewCount||0),likes=+(s.likeCount||0),comments=+(s.commentCount||0);
const perf=views>0?+(((likes+comments)/views*100).toFixed(2)):0;
return [{ json:{ platform:'youtube', external_id:row.youtube_video_id, title:row.title, views, likes, comments, shares:0, performance:perf } }];

const row=$('🔄 Each Video').first().json;
const resp=$input.first().json;
let v={};try{v=resp.data.videos[0];}catch(e){}
const views=+(v.view_count||0),likes=+(v.like_count||0),comments=+(v.comment_count||0),shares=+(v.share_count||0);
const perf=views>0?+(((likes+comments+shares)/views*100).toFixed(2)):0;
return [{ json:{ platform:'tiktok', external_id:row.tiktok_video_id, title:row.title, views, likes, comments, shares, performance:perf } }];

const rows=Array.isArray($input.first().json)?$input.first().json:($input.first().json.data||[]);
if(!rows.length) return [{ json:{ _empty:true, week_start:new Date().toISOString().split('T')[0], top_topics:[], avg_score:0, recommendation:'no_data', insights:{} } }];
const top=rows.slice(0,3).map(r=>r.title);
const avg=+(rows.reduce((s,r)=>s+Number(r.performance||0),0)/rows.length).toFixed(2);
const sys='You are a content strategy analyst (Agent 7). Review weekly performance and recommend next moves. Respond with strict JSON only.';
const usr=`Top titles: ${JSON.stringify(top)}\nAvg engagement score: ${avg}\nReturn JSON: {\"recommendation\":\"excellent|good|needs_improvement\",\"next_topics\":[\"idea1\",\"idea2\",\"idea3\"],\"insight\":\"one actionable insight\"}`;
return [{ json:{ top, avg, requestBody:{ model:'gpt-4o', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.6, max_tokens:500 } } }];

const agg=$('🧮 Aggregate Top Performers').first().json;
if(agg._empty) return [{ json:{ week_start:agg.week_start, top_topics:[], avg_score:0, recommendation:'no_data', insights:{} } }];
const raw=$input.first().json.choices[0].message.content;
let o={};try{o=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/);if(m)o=JSON.parse(m[0]);}
return [{ json:{ week_start:new Date().toISOString().split('T')[0], top_topics:agg.top||[], avg_score:agg.avg||0, recommendation:o.recommendation||'', insights:o } }];
